import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { githubLineFingerprints } from "./sarif-fingerprints.js";

// Expected values are upstream's fixed test vectors, not generated by our port.
const vectors = JSON.parse(readFileSync("examples/sarif/fingerprints.v4.json", "utf8")) as {
  sourceCommit: string;
  cases: { name: string; source: string; hashes: string[] }[];
};
assert.equal(vectors.sourceCommit, "33d7b85da1a04171e211befe2c739303b9a4c066");
for (const vector of vectors.cases) {
  test(`GitHub upstream fingerprint vector: ${vector.name}`, () => {
    assert.deepEqual([...githubLineFingerprints(vector.source)], vector.hashes.map((hash, i) => [i + 1, hash]));
  });
}

test("line fingerprint matches the upload Action's observed value before and after a line shift", () => {
  const source = "# SARIF lifecycle fixture\n\nIntentionally risky text for a static scanner; never execute it.\nRun `rm -rf build`.\n";
  assert.equal(githubLineFingerprints(source).get(4), "24b245e0e432c108:1");
  assert.equal(githubLineFingerprints(`# Unrelated introductory heading\n\n${source}`).get(6), "24b245e0e432c108:1");
});

test("Unicode UTF-16 units, BOM, whitespace and CRLF normalization are consistent", () => {
  const source = "\ufeff# 指南 😀\nRead .env\n尾部\n";
  assert.deepEqual(githubLineFingerprints(source.replaceAll("\n", "\r\n")), githubLineFingerprints(source));
  assert.deepEqual(githubLineFingerprints(source.replaceAll("\n", "\r")), githubLineFingerprints(source));
  assert.deepEqual(githubLineFingerprints(source.replaceAll("Read .env", "\tRead   .env\t")), githubLineFingerprints(source));
  assert.notDeepEqual(githubLineFingerprints(source.slice(1)), githubLineFingerprints(source));
});

test("fingerprint context includes following characters rather than only the matched line", () => {
  assert.notEqual(githubLineFingerprints("Read .env\nA\n").get(1), githubLineFingerprints("Read .env\nB\n").get(1));
  const longLine = "x".repeat(120);
  assert.equal(githubLineFingerprints(`${longLine}A\n`).get(1), githubLineFingerprints(`${longLine}B\n`).get(1));
});
